/**
 * Private object storage for document files (ADR-003). Keys are generated by
 * the application (see storage-key.ts), never taken from user input.
 * Implementations: FilesystemStorage (development, tests) and S3Storage (R2).
 */
export abstract class ObjectStorage {
  /** Stores `body` under `key`, replacing any existing object. */
  abstract put(key: string, body: Buffer, contentType: string): Promise<void>;

  /** Removes the object. Removing a missing object succeeds, so retries are safe. */
  abstract delete(key: string): Promise<void>;
}
